package templgen

import (
	"bytes"
	"encoding/json"
	"fmt"
	"go/format"
	"slices"
	"strconv"
	"strings"

	"starbase/internal/catalog"
)

// Header starts every generated Go file.
const Header = "// Code generated by go tool task templ-wrappers (cmd/templgen) from the components' manifests. DO NOT EDIT.\n\n"

// bootstrap leaves a file of package sb out of the generator's own build
// (go run -tags templgen), which needs only sb's hand-written types: a
// generated file that no longer compiles can't stop its regeneration.
const bootstrap = "//go:build !templgen\n\n"

// Files returns every generated file by its path in the repository.
func Files(m *Model, datastar []byte, siteURL string) (map[string][]byte, error) {
	out := map[string][]byte{}
	add := func(path string, b []byte, err error) error {
		if err != nil {
			return fmt.Errorf("%s: %w", path, err)
		}
		out[path] = b
		return nil
	}
	b, err := m.components(siteURL)
	if err := add("templ/sb/components_gen.go", b, err); err != nil {
		return nil, err
	}
	b, err = m.pins(datastar)
	if err := add("templ/sb/pins_gen.go", b, err); err != nil {
		return nil, err
	}
	b, err = m.registry("sb", "")
	if err := add("templ/sb/registry_gen_test.go", b, err); err != nil {
		return nil, err
	}
	b, err = m.registry("registry", "sb.")
	if err := add("internal/templgen/registry/registry_gen.go", b, err); err != nil {
		return nil, err
	}
	b, err = m.usageTests()
	if err := add("templ/sb/usage_gen_test.go", b, err); err != nil {
		return nil, err
	}
	b, err = m.manifests()
	if err := add("templ/sb/testdata/manifests.json", b, err); err != nil {
		return nil, err
	}
	return out, nil
}

func gofmt(b []byte) ([]byte, error) {
	out, err := format.Source(b)
	if err != nil {
		return nil, fmt.Errorf("%w\n%s", err, b)
	}
	return out, nil
}

// comment writes text as a // comment wrapped at about 76 columns, indent
// before every line. Paragraphs are separated by a blank line; a line that
// starts with "  - " is a list item.
func comment(b *bytes.Buffer, indent, text string) {
	for i, para := range strings.Split(strings.TrimSpace(text), "\n\n") {
		if i > 0 {
			b.WriteString(indent + "//\n")
		}
		var lines []string
		for _, l := range strings.Split(para, "\n") {
			if strings.HasPrefix(l, "  - ") || len(lines) == 0 {
				lines = append(lines, l)
			} else {
				lines[len(lines)-1] += " " + l
			}
		}
		for _, l := range lines {
			first, rest := "// ", "// "
			if item, ok := strings.CutPrefix(l, "  - "); ok {
				l, first, rest = item, "//   - ", "//     "
			}
			wrap(b, indent, first, rest, l)
		}
	}
}

func wrap(b *bytes.Buffer, indent, first, rest, text string) {
	line, prefix := "", first
	for _, w := range strings.Fields(text) {
		if line != "" && 4*len(indent)+len(prefix)+len(line)+1+len(w) > 79 {
			b.WriteString(indent + prefix + line + "\n")
			line, prefix = "", rest
		}
		if line != "" {
			line += " "
		}
		line += w
	}
	if line != "" {
		b.WriteString(indent + prefix + line + "\n")
	}
}

func (m *Model) components(siteURL string) ([]byte, error) {
	var b bytes.Buffer
	b.WriteString(Header + bootstrap + "package sb\n\nimport (\n\t\"context\"\n\t\"io\"\n\n\t\"github.com/a-h/templ\"\n)\n\n")
	b.WriteString("// The components' tags, for ImportsProps.Components.\nconst (\n")
	for _, c := range m.Components {
		fmt.Fprintf(&b, "\tTag%s Tag = %q\n", c.GoName, c.Tag)
	}
	b.WriteString(")\n")
	for _, c := range m.Components {
		c.emit(&b, siteURL)
	}
	return gofmt(b.Bytes())
}

func (c *Component) emit(b *bytes.Buffer, siteURL string) {
	props := c.GoName + "Props"
	b.WriteString("\n")
	doc := fmt.Sprintf("%s renders <%s>: %s", c.GoName, c.Tag, strings.TrimSuffix(c.Summary, "."))
	doc += ".\n\nChildren render inside the element."
	if len(c.Manifest.Slots) > 0 {
		doc += " Its slots (give a child slot=\"<name>\" for a named one):"
		for _, s := range c.Manifest.Slots {
			name := s.Name
			if name == "" || name == "default" {
				name = "default"
			}
			doc += "\n  - " + name + ": " + oneLine(s.Description)
		}
	}
	if len(c.Manifest.Events) > 0 {
		doc += "\n\nEvents, to listen to with Attrs (\"data-on:" + c.Manifest.Events[len(c.Manifest.Events)-1].Name + "\"):"
		for _, e := range c.Manifest.Events {
			doc += "\n  - " + e.Name + ": " + oneLine(e.Description)
		}
	}
	doc += "\n\nDocs: " + strings.TrimSuffix(siteURL, "/") + "/components/" + c.Slug
	comment(b, "", doc)
	fmt.Fprintf(b, "func %s(p %s) templ.Component {\n", c.GoName, props)
	b.WriteString("\treturn templ.ComponentFunc(func(ctx context.Context, w io.Writer) error {\n")
	fmt.Fprintf(b, "\t\tused(ctx, Tag%s)\n", c.GoName)
	fmt.Fprintf(b, "\t\te := newElement(%q, p.ID, p.Class, p.Attrs)\n", c.Tag)
	for _, f := range c.Fields {
		a, v := strconv.Quote(f.Prop.Attribute), "p."+f.GoName
		switch f.Kind {
		case KindString:
			fmt.Fprintf(b, "\t\te.str(%s, %s)\n", a, v)
		case KindURL:
			fmt.Fprintf(b, "\t\te.url(%s, %s)\n", a, v)
		case KindStringPtr:
			fmt.Fprintf(b, "\t\te.strPtr(%s, %s)\n", a, v)
		case KindBool:
			fmt.Fprintf(b, "\t\te.bool(%s, %s)\n", a, v)
		case KindFlag:
			fmt.Fprintf(b, "\t\te.flag(%s, %s)\n", a, v)
		case KindEnum:
			vals := make([]string, len(f.Enum))
			for i, e := range f.Enum {
				vals[i] = strconv.Quote(e.Value)
			}
			fmt.Fprintf(b, "\t\te.enum(%s, string(%s), %s)\n", a, v, strings.Join(vals, ", "))
		case KindNumber:
			fmt.Fprintf(b, "\t\te.num(%s, %s)\n", a, v)
		case KindNumberPtr:
			fmt.Fprintf(b, "\t\te.numPtr(%s, %s)\n", a, v)
		case KindJSON:
			fmt.Fprintf(b, "\t\te.json(%s, %s, %s == nil)\n", a, v, v)
		}
	}
	b.WriteString("\t\treturn e.render(ctx, w)\n\t})\n}\n\n")

	comment(b, "", fmt.Sprintf("%s are the props of <%s> (%s).", props, c.Tag, c.GoName))
	fmt.Fprintf(b, "type %s struct {\n", props)
	b.WriteString("\t// ID is the element's id.\n\tID string\n")
	b.WriteString("\t// Class is the element's class.\n\tClass string\n")
	b.WriteString("\t// Attrs are written after the props' attributes, and win over a prop\n\t// that writes the same attribute: Datastar attributes (data-on:*,\n\t// data-bind, data-attr:*, data-preserve-attr), aria-*, slot, style.\n\tAttrs templ.Attributes\n")
	for _, f := range c.Fields {
		b.WriteString("\n")
		comment(b, "\t", f.doc())
		fmt.Fprintf(b, "\t%s %s\n", f.GoName, f.GoType)
	}
	b.WriteString("}\n")

	for _, f := range c.Fields {
		if f.Kind != KindEnum {
			continue
		}
		b.WriteString("\n")
		comment(b, "", fmt.Sprintf("%s is a value of %s.%s: %s", f.GoType, props, f.GoName, oneLine(f.description())))
		fmt.Fprintf(b, "type %s string\n\n", f.GoType)
		fmt.Fprintf(b, "// The values of %s; the zero value leaves the attribute out (%q).\nconst (\n", f.GoType, f.Default)
		for _, e := range f.Enum {
			fmt.Fprintf(b, "\t%s %s = %q\n", e.GoName, f.GoType, e.Value)
		}
		b.WriteString(")\n")
	}
}

func oneLine(s string) string { return strings.Join(strings.Fields(s), " ") }

func (f *Field) description() string {
	if f.Prop.Docs == nil {
		return ""
	}
	return strings.TrimSpace(f.Prop.Docs.Description)
}

// doc is the field's doc comment: the prop's docs, then its attribute and
// what the zero value means.
func (f *Field) doc() string {
	d := f.description()
	if d != "" && !strings.HasSuffix(d, ".") && !strings.HasSuffix(d, ")") {
		d += "."
	}
	a := "Attribute " + f.Prop.Attribute
	switch f.Kind {
	case KindURL:
		a += `; empty leaves it out. Sanitized like templ's href: a scheme other than http, https, mailto, tel, ftp and ftps becomes about:invalid#TemplFailedSanitizationURL (a templ.SafeURL in Attrs wins)`
	case KindString:
		if s, _ := f.Default.(string); s != "" {
			a += fmt.Sprintf("; empty leaves it out, for the default %q", s)
		}
	case KindStringPtr:
		a += "; nil leaves it out"
		if s, _ := f.Default.(string); s != "" {
			a += fmt.Sprintf(" (the default is %q)", s)
		}
		if serverWord[f.key()] {
			a += `, Str("") sends an empty value, which wins over the user's`
		} else {
			a += `, Str("") writes it empty`
		}
	case KindBool:
		a += ", by presence"
	case KindFlag:
		a += `; Default leaves it out (on), Off writes "false", On "true"`
	case KindEnum:
		a += fmt.Sprintf("; default %q", f.Default)
	case KindNumber:
		a += "; 0 (the default) leaves it out"
	case KindNumberPtr:
		a += "; nil leaves it out"
		if n, ok := f.Default.(float64); ok && n != 0 {
			a += " (the default is " + strconv.FormatFloat(n, 'f', -1, 64) + ")"
		}
		if serverWord[f.key()] {
			a += ", Num(0) sends 0, which wins over the user's value"
		} else if presence[f.key()] {
			a += ", Num(0) writes 0"
		}
	case KindJSON:
		a += ", as JSON; nil leaves it out"
		if f.Default != nil && !isEmpty(f.Default) {
			a += " (the default is " + prettyJSON(f.Prop.Default) + ")"
		}
	}
	return strings.TrimSpace(d + " " + a + ".")
}

func (f *Field) key() string { return f.tag + "." + f.Prop.Attribute }

func isEmpty(v any) bool {
	switch v := v.(type) {
	case []any:
		return len(v) == 0
	case map[string]any:
		return len(v) == 0
	}
	return false
}

// pins writes the versions Imports loads: every component's one-file
// bundle, the files it loads lazily and the components it renders, the
// Datastar build and the catalog snapshot, each with its SRI hash.
func (m *Model) pins(datastar []byte) ([]byte, error) {
	cat := m.Catalog
	var b bytes.Buffer
	b.WriteString(Header + bootstrap + "package sb\n\n")
	snap := *cat
	snap.PinBuild(datastar)
	auto := catalog.AutoloaderJS(&snap, "../")
	fmt.Fprintf(&b, "const (\n\tdatastarPath = %q\n\tdatastarIntegrity = %q\n\tsnapshot = %q\n\tsnapshotIntegrity = %q\n)\n\n",
		"/c/"+catalog.DatastarSlug+"@"+catalog.VersionHash(datastar)+"/"+catalog.DatastarFile, catalog.SRI(datastar),
		snap.Hash, catalog.SRI([]byte(auto)))
	b.WriteString("var pinOrder = []Tag{")
	for i, c := range m.Components {
		if i > 0 {
			b.WriteString(", ")
		}
		b.WriteString("Tag" + c.GoName)
	}
	b.WriteString("}\n\nvar pins = map[Tag]pin{\n")
	for _, c := range m.Components {
		bundle, err := cat.BundleOf(c.Component)
		if err != nil {
			return nil, err
		}
		mins, err := cat.MinFiles(c.Component)
		if err != nil {
			return nil, err
		}
		files, err := cat.ModuleFiles(c.Component)
		if err != nil {
			return nil, err
		}
		fmt.Fprintf(&b, "\tTag%s: {\n\t\tbundle: %q,\n\t\tintegrity: %q,\n", c.GoName, c.VersionedBundle(), catalog.SRI(bundle.Body))
		if len(bundle.Lazy) > 0 {
			b.WriteString("\t\tlazy: []pinnedFile{\n")
			for _, p := range bundle.Lazy {
				body, ok := mins[p]
				if !ok {
					body, ok = files[p] // a vendored .min.js is its own minified file
				}
				if !ok {
					return nil, fmt.Errorf("%s: no minified %s", c.Slug, p)
				}
				fmt.Fprintf(&b, "\t\t\t{%q, %q},\n", c.Slug+"@"+c.Hash+"/"+p, catalog.SRI(body))
			}
			b.WriteString("\t\t},\n")
		}
		if deps := cat.Deps(c.Component); len(deps) > 0 {
			b.WriteString("\t\tdeps: []Tag{")
			for i, d := range deps {
				dc, _ := m.Get(d.Tag)
				if i > 0 {
					b.WriteString(", ")
				}
				b.WriteString("Tag" + dc.GoName)
			}
			b.WriteString("},\n")
		}
		b.WriteString("\t},\n")
	}
	b.WriteString("}\n")
	return gofmt(b.Bytes())
}

// registry writes a table of every component, for tests that render each
// with props they fill: in package pkg, with sb's names qualified by qual.
func (m *Model) registry(pkg, qual string) ([]byte, error) {
	var b bytes.Buffer
	b.WriteString(Header)
	if pkg == "registry" {
		b.WriteString("// Package registry lists every wrapper of package sb, for tests that\n// render each component through it.\n")
	}
	b.WriteString("package " + pkg + "\n\nimport (\n\t\"github.com/a-h/templ\"\n")
	if qual != "" {
		b.WriteString("\n\t\"" + sbPath + "\"\n")
	}
	b.WriteString(")\n\n")
	b.WriteString("// Entry is a wrapper: New returns a pointer to its zero props, Render\n// renders such a pointer.\ntype Entry struct {\n\tTag string\n\tNew func() any\n\tRender func(props any) templ.Component\n}\n\n")
	b.WriteString("// Entries are every wrapper, by slug.\nvar Entries = []Entry{\n")
	for _, c := range m.Components {
		fmt.Fprintf(&b, "\t{%q, func() any { return &%s%sProps{} }, func(p any) templ.Component { return %s%s(*p.(*%s%sProps)) }},\n",
			c.Tag, qual, c.GoName, qual, c.GoName, qual, c.GoName)
	}
	b.WriteString("}\n")
	return gofmt(b.Bytes())
}

// manifests writes every manifest, for the module's tests, which check the
// wrappers against them without the repository around.
func (m *Model) manifests() ([]byte, error) {
	type entry struct {
		Slug string `json:"slug"`
		*catalog.Manifest
	}
	var all []entry
	for _, c := range m.Components {
		all = append(all, entry{c.Slug, c.Manifest})
	}
	slices.SortFunc(all, func(a, b entry) int { return strings.Compare(a.Slug, b.Slug) })
	b, err := json.MarshalIndent(all, "", "  ")
	return append(b, '\n'), err
}
